from itertools import product

def is_magic_sequence(seq):
    n = len(seq)
    for i in range(n):
        if seq[i] != seq.count(i):
            return False
    return True

# Brute force approach - but the search space is too large
# Let's use constraint solving instead

# We know:
# - sum(x[i]) = 9 (length of sequence)
# - sum(i * x[i]) = 9 (sum of elements)
# - x[4] = 0

# Let's use a smarter approach with backtracking
def solve_magic_sequence(n, fixed=None):
    if fixed is None:
        fixed = {}

    # x[i] represents count of i in sequence
    # Constraints:
    # 1. sum(x[i]) = n
    # 2. sum(i * x[i]) = n
    # 3. x[i] >= 0 for all i
    # 4. x[fixed_key] = fixed_value for fixed assignments

    # Use backtracking with pruning
    def backtrack(idx, current, remaining_sum, remaining_weighted_sum):
        if idx == n:
            if remaining_sum == 0 and remaining_weighted_sum == 0:
                # Verify it's actually a magic sequence
                if is_magic_sequence(current):
                    return current
            return None

        if idx in fixed:
            val = fixed[idx]
            if val < 0 or val > remaining_sum:
                return None
            if idx * val > remaining_weighted_sum:
                return None
            current.append(val)
            result = backtrack(idx + 1, current, remaining_sum - val, remaining_weighted_sum - idx * val)
            if result:
                return result
            current.pop()
            return None

        # Try values from 0 to remaining_sum
        max_val = min(remaining_sum, remaining_weighted_sum // idx if idx > 0 else remaining_sum)
        for val in range(max_val + 1):
            current.append(val)
            result = backtrack(idx + 1, current, remaining_sum - val, remaining_weighted_sum - idx * val)
            if result:
                return result
            current.pop()

        return None

    return backtrack(0, [], n, n)

# Solve with x[4] = 0
result = solve_magic_sequence(9, fixed={4: 0})
print("Result:", result)

if result:
    # Verify
    print("Verification:")
    for i in range(9):
        print(f"x[{i}] = {result[i]}, count of {i} in sequence = {result.count(i)}")
    print("Is magic:", is_magic_sequence(result))
